function translate(table, pageSize, vaddrs) {
  var out = [];
  for (var i = 0; i < vaddrs.length; i++) {
    var page = Math.floor(vaddrs[i] / pageSize), frame = table[page];
    out.push(frame === undefined || frame === null ? -1 : frame * pageSize + (vaddrs[i] % pageSize));
  }
  return out;
}
